effect.shader:
float gmScreen(vec2 uv,float a,float lum){float c=cos(a),s=sin(a);vec2 p=mat2(c,-s,s,c)*(uv-0.5)*frequency;vec2 f=fract(p)-0.5;float d=length(f);if(pattern==1)d=abs(f.y)*1.4;if(pattern==2)d=(abs(f.x)+abs(f.y))*0.72;float r=sqrt(clamp(1.0-lum,0.0,1.0))*0.68*dotGain;return 1.0-smoothstep(r-softness,r+softness,d);}
void main(){vec2 uv=acScreenNorm;vec4 src=texture2DCv(inputImg.texture,uv);float lum=dot(src.rgb,vec3(0.2126,0.7152,0.0722));vec3 result;
if(pattern==3){float c=gmScreen(uv,angle+0.2618,src.r),m=gmScreen(uv,angle+1.309,src.g),y=gmScreen(uv,angle,src.b),k=gmScreen(uv,angle+0.7854,lum);result=paperColor.rgb*(1.0-k)*vec3(1.0-c,1.0-m,1.0-y);}
else{float mask=gmScreen(uv,angle,lum);result=mix(paperColor.rgb,inkColor.rgb,mask);}
result=mix(result,result*src.rgb,sourceColor);gl_FragColor=vec4(mix(src.rgb,result,mixAmount),src.a);}
